00050     public static function process()
00051     {
00052         global $bearsamppTools;
00053 
00054         $fontName = 'CaskaydiaMono NF'; // Default Nerd Font
00055 
00056         // Collect all console window titles that need font configuration
00057         $titles = [];
00058         $titles[] = $bearsamppTools->getPowerShell()->getTabTitleDefault();
00059         $titles[] = $bearsamppTools->getPowerShell()->getTabTitlePowershell();
00060         $titles[] = 'Console';
00061         $titles[] = 'Bearsampp Powershell Console'; // Fallback casing
00062 
00063         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitlePear(); } catch (Exception $e) {}
00064         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleMysql(); } catch (Exception $e) {}
00065         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleMariadb(); } catch (Exception $e) {}
00066         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitlePostgresql(); } catch (Exception $e) {}
00067         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleGit(); } catch (Exception $e) {}
00068         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleNodejs(); } catch (Exception $e) {}
00069         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleComposer(); } catch (Exception $e) {}
00070         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitlePython(); } catch (Exception $e) {}
00071         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleRuby(); } catch (Exception $e) {}
00072         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitlePerl(); } catch (Exception $e) {}
00073         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleGhostscript(); } catch (Exception $e) {}
00074         try { $titles[] = $bearsamppTools->getPowerShell()->getTabTitleNgrok(); } catch (Exception $e) {}
00075 
00076         // Also include generic/short titles
00077         $shortTitles = ["Composer", "Ghostscript", "ngrok", "PEAR", "Perl", "Ruby", "Git", "Python", "MariaDB", "MySQL", "PostgreSQL", "Node.js"];
00078         $allTitles = array_unique(array_merge($titles, $shortTitles));
00079 
00080         // Build a single .reg file with all HKCU Console font settings.
00081         // This replaces ~140 individual exec("reg add ...") calls, each of which
00082         // would spawn a separate process and potentially flash a console window.
00083         $regContent = "Windows Registry Editor Version 5.00\r\n";
00084 
00085         // Global HKCU\Console defaults
00086         $regContent .= "\r\n[HKEY_CURRENT_USER\\Console]\r\n";
00087         $regContent .= '"FaceName"="' . $fontName . '"' . "\r\n";
00088         $regContent .= '"FontFamily"=dword:00000036' . "\r\n";
00089         $regContent .= '"CodePage"=dword:0000fde9' . "\r\n";
00090 
00091         // Per-title settings
00092         foreach ($allTitles as $title) {
00093             if (empty($title)) continue;
00094             $regContent .= "\r\n[HKEY_CURRENT_USER\\Console\\" . $title . "]\r\n";
00095             $regContent .= '"FaceName"="' . $fontName . '"' . "\r\n";
00096             $regContent .= '"FontFamily"=dword:00000036' . "\r\n";
00097             $regContent .= '"FontSize"=dword:00100000' . "\r\n";
00098             $regContent .= '"FontWeight"=dword:00000190' . "\r\n";
00099             $regContent .= '"CodePage"=dword:0000fde9' . "\r\n";
00100             $regContent .= '"ScreenBufferSize"=dword:0bb8006e' . "\r\n";
00101             $regContent .= '"WindowSize"=dword:001e006e' . "\r\n";
00102         }
00103 
00104         // Register as a valid TrueType console font (HKCU only â€” no elevation needed)
00105         $regContent .= "\r\n[HKEY_CURRENT_USER\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Console\\TrueTypeFont]\r\n";
00106         $regContent .= '"0"="' . $fontName . '"' . "\r\n";
00107         $regContent .= '"00"="' . $fontName . '"' . "\r\n";
00108         $regContent .= '"000"="' . $fontName . '"' . "\r\n";
00109 
00110         // Write and import the .reg file in a single process â€” zero flashing windows
00111         $tmpReg = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'bearsampp_console_font.reg';
00112 
00113         $bytes = file_put_contents($tmpReg, $regContent);
00114         if ($bytes === false || $bytes === 0) {
00115             return false;
00116         }
00117 
00118         $cmd = 'reg import "' . $tmpReg . '"';
00119         $exitCode = 1;
00120         try {
00121             $wsh = new COM('WScript.Shell');
00122             $exitCode = $wsh->Run($cmd, 0, true);
00123         } catch (Throwable $e) {
00124             $output = [];
00125             exec($cmd, $output, $exitCode);
00126         }
00127 
00128         @unlink($tmpReg);
00129 
00130         if ($exitCode !== 0) {
00131             return false;
00132         }
00133 
00134         return true;
00135     }
