00459     private static function getTabRubySection()
00460     {
00461         global $bearsamppRoot, $bearsamppTools;
00462 
00463         // Check if Ruby exists first
00464         if (!file_exists($bearsamppTools->getRuby()->getExe())) {
00465             $shell = $bearsamppTools->getPowerShell()->getShell('echo ' . $bearsamppTools->getRuby()->getExe() . ' not found');
00466         } else {
00467             // Use irb (Interactive Ruby) for an interactive shell
00468             $rubyDir = dirname($bearsamppTools->getRuby()->getExe());
00469             $irbExe = $rubyDir . '/irb.bat';
00470             
00471             // Check if irb.bat exists, otherwise try irb.cmd or just use ruby with -i flag
00472             if (file_exists($irbExe)) {
00473                 $shell = $bearsamppTools->getPowerShell()->getShell('&quot;' . $irbExe . '&quot;');
00474             } elseif (file_exists($rubyDir . '/irb.cmd')) {
00475                 $shell = $bearsamppTools->getPowerShell()->getShell('&quot;' . $rubyDir . '/irb.cmd' . '&quot;');
00476             } elseif (file_exists($rubyDir . '/irb')) {
00477                 $shell = $bearsamppTools->getPowerShell()->getShell('&quot;' . $rubyDir . '/irb' . '&quot;');
00478             } else {
00479                 // Fallback to just opening a shell in the Ruby directory
00480                 $shell = $bearsamppTools->getPowerShell()->getShell();
00481             }
00482         }
00483 
00484         return self::getTab(
00485                 $bearsamppTools->getPowerShell()->getTabTitleRuby(),
00486                 null, // self::ICON_RUBY - Icon not supported in native PowerShell console
00487                 $shell,
00488                 Path::getWwwPath()
00489             ) . PHP_EOL;
00490     }
