00597     private static function getTab($title, $icon, $shell, $initDir)
00598     {
00599         global $bearsamppCore;
00600         // Icon parameter is ignored as native PowerShell console does not support custom icons
00601         // Return tab information as a formatted string
00602         return "Title: $title | Shell: $shell | InitDir: $initDir";
00603     }
